"use client"

import * as React from "react"
import { cn } from "cn"
import { SearchIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Chip, ChipGroup, ChipList, ChipTag } from "@/components/tecton/chip"
import {
  SelectField,
  SelectFieldItem,
} from "@/components/tecton/select-field"
import { TextField, TextFieldInput } from "@/components/tecton/text-field"

import { fields, statusMeta, typeMeta, type WellStatus, type WellType } from "../data"

export type WellsFilter = {
  query: string
  field: string
  type: WellType | "all"
  statuses: WellStatus[]
}

export const emptyFilter: WellsFilter = {
  query: "",
  field: "all",
  type: "all",
  statuses: [],
}

type WellsFilterBarProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  value: WellsFilter
  onChange: (next: WellsFilter) => void
  /** Number of rows matching the current filter. */
  resultCount?: number
}

function WellsFilterBar({
  className,
  value,
  onChange,
  resultCount,
  ...props
}: WellsFilterBarProps) {
  const set = <K extends keyof WellsFilter>(key: K, next: WellsFilter[K]) =>
    onChange({ ...value, [key]: next })

  const toggleStatus = (status: WellStatus) =>
    set(
      "statuses",
      value.statuses.includes(status)
        ? value.statuses.filter((item) => item !== status)
        : [...value.statuses, status]
    )

  const active =
    value.query.trim() !== "" ||
    value.field !== "all" ||
    value.type !== "all" ||
    value.statuses.length > 0

  return (
    <div
      data-slot="wells-filter-bar"
      className={cn("flex flex-col gap-3", className)}
      {...props}
    >
      <div className="flex flex-col gap-3 md:flex-row md:items-end">
        <TextField
          aria-label="Search wells"
          className="md:max-w-xs"
          value={value.query}
          onChange={(next) => set("query", next)}
        >
          <div className="relative">
            <SearchIcon
              className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
              aria-hidden
            />
            <TextFieldInput placeholder="Search by name, rig or operator…" className="pl-8" />
          </div>
        </TextField>
        <SelectField
          aria-label="Field"
          className="md:w-48"
          selectedKey={value.field}
          onSelectionChange={(key) => set("field", String(key))}
        >
          <SelectFieldItem id="all" textValue="All fields">
            All fields
          </SelectFieldItem>
          {fields.map((field) => (
            <SelectFieldItem key={field} id={field} textValue={field}>
              {field}
            </SelectFieldItem>
          ))}
        </SelectField>
        <SelectField
          aria-label="Well type"
          className="md:w-44"
          selectedKey={value.type}
          onSelectionChange={(key) => set("type", String(key) as WellsFilter["type"])}
        >
          <SelectFieldItem id="all" textValue="All types">
            All types
          </SelectFieldItem>
          {(Object.keys(typeMeta) as WellType[]).map((type) => (
            <SelectFieldItem key={type} id={type} textValue={typeMeta[type]}>
              {typeMeta[type]}
            </SelectFieldItem>
          ))}
        </SelectField>
        {active && (
          <Button
            variant="ghost"
            size="sm"
            className="md:ml-auto"
            onPress={() => onChange(emptyFilter)}
          >
            <XIcon /> Clear filters
          </Button>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-muted-foreground">Status</span>
        <div className="flex flex-wrap gap-1.5" role="group" aria-label="Status filters">
          {(Object.keys(statusMeta) as WellStatus[]).map((status) => {
            const selected = value.statuses.includes(status)
            return (
              <Chip
                key={status}
                size="sm"
                color={selected ? statusMeta[status].color : "default"}
                variant={selected ? "filled" : "outlined"}
                aria-pressed={selected}
                onPress={() => toggleStatus(status)}
              >
                {statusMeta[status].label}
              </Chip>
            )
          })}
        </div>
        {value.statuses.length > 0 && (
          <ChipGroup
            aria-label="Active status filters"
            className="ml-auto"
            onRemove={(keys) =>
              set(
                "statuses",
                value.statuses.filter((status) => !keys.has(status))
              )
            }
          >
            <ChipList>
              {value.statuses.map((status) => (
                <ChipTag key={status} id={status} size="xs" textValue={statusMeta[status].label}>
                  {statusMeta[status].label}
                </ChipTag>
              ))}
            </ChipList>
          </ChipGroup>
        )}
        {typeof resultCount === "number" && (
          <span className="ml-auto font-mono text-xs text-muted-foreground tabular-nums">
            {resultCount} {resultCount === 1 ? "well" : "wells"}
          </span>
        )}
      </div>
    </div>
  )
}

export { WellsFilterBar }
export type { WellsFilterBarProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import { DatabaseIcon, MoreVerticalIcon, PlusIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Chip } from "@/components/tecton/chip"
import {
  createDataTableColumns,
  DataTable,
} from "@/components/tecton/data-table"

import { formatDate, statusMeta, typeMeta, type Well } from "../data"

const columns = createDataTableColumns<Well>()

function createWellColumns(onOpen?: (well: Well) => void) {
  return [
    columns.accessor("name", {
      header: "Well",
      cell: ({ getValue }) => (
        <span className="font-mono font-medium tabular-nums">{getValue()}</span>
      ),
    }),
    columns.accessor("field", { header: "Field" }),
    columns.accessor("type", {
      header: "Type",
      cell: ({ getValue }) => typeMeta[getValue()],
    }),
    columns.accessor("status", {
      header: "Status",
      cell: ({ getValue }) => {
        const meta = statusMeta[getValue()]
        return (
          <Chip size="xs" color={meta.color} variant="outlined">
            {meta.label}
          </Chip>
        )
      },
    }),
    columns.accessor("td", {
      header: "TD (m MD)",
      cell: ({ getValue }) => (
        <span className="block text-right font-mono tabular-nums">
          {getValue().toLocaleString()}
        </span>
      ),
    }),
    columns.accessor("spud", {
      header: "Spud",
      cell: ({ getValue }) => (
        <span className="font-mono tabular-nums">{formatDate(getValue())}</span>
      ),
    }),
    columns.accessor("rig", { header: "Rig" }),
    columns.display({
      id: "actions",
      header: "",
      enableSorting: false,
      cell: ({ row }) => (
        <span className="flex justify-end">
          <DropdownMenuTrigger>
            <Button variant="ghost" size="icon-xs" aria-label={`Actions for ${row.original.name}`}>
              <MoreVerticalIcon />
            </Button>
            <DropdownMenu placement="bottom end">
              <DropdownMenuItem onAction={() => onOpen?.(row.original)}>Open</DropdownMenuItem>
              <DropdownMenuItem>Add to project</DropdownMenuItem>
              <DropdownMenuItem>Export logs</DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem variant="destructive">Archive</DropdownMenuItem>
            </DropdownMenu>
          </DropdownMenuTrigger>
        </span>
      ),
    }),
  ]
}

type WellsTableProps = Omit<
  React.ComponentProps<typeof DataTable<Well>>,
  "columns" | "data"
> & {
  data: Well[]
  onOpen?: (well: Well) => void
}

function WellsTable({ className, data, onOpen, ...props }: WellsTableProps) {
  const wellColumns = React.useMemo(() => createWellColumns(onOpen), [onOpen])
  return (
    <DataTable
      data-slot="wells-table"
      label="Wells"
      className={cn("bg-card", className)}
      columns={wellColumns}
      data={data}
      pageSize={10}
      enableSelection
      smallScreen
      getRowId={(row) => row.id}
      onRowAction={(_, row) => onOpen?.(row)}
      {...props}
    />
  )
}

type WellsEmptyStateProps = React.ComponentProps<typeof Empty> & {
  /** True when a filter is active (offers "clear filters" instead of "add well"). */
  filtered?: boolean
  onClear?: () => void
  onCreate?: () => void
}

function WellsEmptyState({
  className,
  filtered = false,
  onClear,
  onCreate,
  ...props
}: WellsEmptyStateProps) {
  return (
    <Empty
      data-slot="wells-empty-state"
      className={cn("rounded-md border border-dashed border-border bg-card/50", className)}
      {...props}
    >
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <DatabaseIcon />
        </EmptyMedia>
        <EmptyTitle>{filtered ? "No wells match" : "No wells yet"}</EmptyTitle>
        <EmptyDescription>
          {filtered
            ? "Try a different search term, or clear the field, type and status filters."
            : "Import wells from the corporate database or create the first planned well."}
        </EmptyDescription>
      </EmptyHeader>
      <EmptyContent className="flex-row justify-center">
        {filtered ? (
          <Button variant="outline" size="sm" onPress={onClear}>
            Clear filters
          </Button>
        ) : (
          <>
            <Button variant="outline" size="sm">
              Import
            </Button>
            <Button size="sm" onPress={onCreate}>
              <PlusIcon /> New well
            </Button>
          </>
        )}
      </EmptyContent>
    </Empty>
  )
}

export { WellsTable, WellsEmptyState, createWellColumns }
export type { WellsTableProps, WellsEmptyStateProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import { DownloadIcon, PlusIcon, UploadIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  PageHeader,
  PageHeaderActions,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderEyebrow,
  PageHeaderTitle,
} from "@/components/tecton/page-header"

import {
  emptyFilter,
  WellsFilterBar,
  type WellsFilter,
} from "./components/wells-filter-bar"
import { WellsEmptyState, WellsTable } from "./components/wells-table"
import { wells as allWells, type Well } from "./data"

type WellsListPageProps = React.ComponentProps<"div"> & {
  wells?: Well[]
  /** Render the empty-state variant (no wells at all). */
  empty?: boolean
  onOpen?: (well: Well) => void
}

function applyFilter(wells: Well[], filter: WellsFilter): Well[] {
  const query = filter.query.trim().toLowerCase()
  return wells.filter((well) => {
    if (filter.field !== "all" && well.field !== filter.field) return false
    if (filter.type !== "all" && well.type !== filter.type) return false
    if (filter.statuses.length > 0 && !filter.statuses.includes(well.status)) return false
    if (
      query &&
      ![well.name, well.rig, well.operator, well.field].some((text) =>
        text.toLowerCase().includes(query)
      )
    )
      return false
    return true
  })
}

/**
 * Wells list page — page header with actions, a filter bar (search,
 * selects, status chips) and a paginated, selectable `DataTable`, with
 * an empty state for no data / no matches.
 */
function WellsListPage({
  className,
  wells = allWells,
  empty = false,
  onOpen,
  ...props
}: WellsListPageProps) {
  const [filter, setFilter] = React.useState<WellsFilter>(emptyFilter)
  const source = empty ? [] : wells
  const rows = React.useMemo(() => applyFilter(source, filter), [source, filter])
  const filtered = JSON.stringify(filter) !== JSON.stringify(emptyFilter)

  return (
    <div
      data-slot="wells-list-page"
      className={cn(
        "flex min-h-svh w-full flex-col gap-6 bg-background px-4 py-8 text-foreground md:px-8",
        className
      )}
      {...props}
    >
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderEyebrow>Inventory</PageHeaderEyebrow>
          <PageHeaderTitle>Wells</PageHeaderTitle>
          <PageHeaderDescription>
            All wells across your licences. Select rows to add them to a
            project or export their logs.
          </PageHeaderDescription>
        </PageHeaderContent>
        <PageHeaderActions>
          <Button variant="ghost" size="sm">
            <DownloadIcon /> Export
          </Button>
          <Button variant="outline" size="sm">
            <UploadIcon /> Import
          </Button>
          <Button size="sm">
            <PlusIcon /> New well
          </Button>
        </PageHeaderActions>
      </PageHeader>

      {source.length > 0 && (
        <WellsFilterBar value={filter} onChange={setFilter} resultCount={rows.length} />
      )}

      {rows.length === 0 ? (
        <WellsEmptyState
          filtered={source.length > 0 && filtered}
          onClear={() => setFilter(emptyFilter)}
        />
      ) : (
        <WellsTable data={rows} onOpen={onOpen} />
      )}
    </div>
  )
}

/** Route-ready page. */
export default function WellsListRoute() {
  return <WellsListPage />
}

export { WellsListPage, WellsFilterBar, WellsTable, WellsEmptyState, applyFilter }
export { wells, statusMeta, typeMeta, fields, formatDate } from "./data"
export { emptyFilter } from "./components/wells-filter-bar"
export type { WellsListPageProps }
export type { WellsFilter } from "./components/wells-filter-bar"
export type { Well, WellStatus, WellType } from "./data"
